-- 단어 설명용 그래프·표 (words.visuals). 형식은 src/types.ts의 WordVisual 참고.
-- ecos 항목은 ecos-series 함수(ECOS_API_KEY 필요)가 한국은행 통계를 불러온다. 개념 그래프 수치는 설명용 예시.
-- 재실행해도 같은 값으로 덮어쓴다.

ALTER TABLE public.words ADD COLUMN IF NOT EXISTS visuals JSONB;

UPDATE public.words SET visuals = '[{"type":"line","title":"100만 원을 연 10%로 10년 맡기면","unit":"만 원","x":["0년","1년","2년","3년","4년","5년","6년","7년","8년","9년","10년"],"series":[{"name":"복리","values":[100.0,110.0,121.0,133.1,146.4,161.1,177.2,194.9,214.4,235.8,259.4]},{"name":"단리","values":[100,110,120,130,140,150,160,170,180,190,200]}],"caption":"단리: 처음 넣은 100만 원에만 이자가 붙어요.\n1년 +10만 → 2년 +10만 → 3년 +10만\n\n복리: 통장에 있는 돈 전체에 이자가 붙어요.\n1년 +10만 → 2년 +11만 → 3년 +12.1만\n작년 이자도 올해 이자를 만들어요.\n\n10년째 한 해 이자는 단리 10만 원, 복리 23.6만 원이에요.\n(세금·수수료 제외 예시)"},{"type":"table","title":"단리와 복리 비교","columns":["구분","단리","복리"],"rows":[["이자가 붙는 곳","원금에만","원금 + 쌓인 이자"],["10년 뒤 (100만 원, 연 10%)","200만 원","약 259만 원"],["시간이 지날수록","일정하게 증가","점점 빠르게 증가"]]}]'::jsonb WHERE id = 724 AND word = '복리';
UPDATE public.words SET visuals = '[{"type":"line","title":"100만 원을 연 10%로 10년 맡기면","unit":"만 원","x":["0년","1년","2년","3년","4년","5년","6년","7년","8년","9년","10년"],"series":[{"name":"복리","values":[100.0,110.0,121.0,133.1,146.4,161.1,177.2,194.9,214.4,235.8,259.4]},{"name":"단리","values":[100,110,120,130,140,150,160,170,180,190,200]}],"caption":"단리: 처음 넣은 100만 원에만 이자가 붙어요.\n1년 +10만 → 2년 +10만 → 3년 +10만\n\n복리: 통장에 있는 돈 전체에 이자가 붙어요.\n1년 +10만 → 2년 +11만 → 3년 +12.1만\n작년 이자도 올해 이자를 만들어요.\n\n10년째 한 해 이자는 단리 10만 원, 복리 23.6만 원이에요.\n(세금·수수료 제외 예시)"},{"type":"table","title":"단리와 복리 비교","columns":["구분","단리","복리"],"rows":[["이자가 붙는 곳","원금에만","원금 + 쌓인 이자"],["10년 뒤 (100만 원, 연 10%)","200만 원","약 259만 원"],["시간이 지날수록","일정하게 증가","점점 빠르게 증가"]]}]'::jsonb WHERE id = 167 AND word = '단리';
UPDATE public.words SET visuals = '[{"type":"line","title":"피자를 한 조각씩 더 먹을 때 만족도 (예시)","unit":"점","x":["1조각","2조각","3조각","4조각","5조각","6조각"],"series":[{"name":"한 조각 더 먹을 때 느는 만족(한계효용)","values":[10,8,6,4,2,0]},{"name":"전체 만족(총효용)","values":[10,18,24,28,30,30]}],"caption":"조각이 늘수록 한 조각이 주는 추가 만족은 줄어들어요. 한계효용이 0이 되면 더 먹어도 전체 만족이 늘지 않아요."}]'::jsonb WHERE id = 645 AND word = '한계효용';
UPDATE public.words SET visuals = '[{"type":"line","title":"같은 밭에 일꾼을 한 명씩 더 넣을 때 수확량 (예시)","unit":"kg","x":["1명","2명","3명","4명","5명","6명"],"series":[{"name":"한 명 더 넣을 때 느는 수확","values":[10,15,11,7,4,2]},{"name":"전체 수확","values":[10,25,36,43,47,49]}],"caption":"땅(고정된 생산요소)은 그대로인데 일꾼만 늘리면, 어느 순간부터 한 명이 더해 주는 수확이 점점 줄어요."}]'::jsonb WHERE id = 324 AND word = '수확체감의 법칙';
UPDATE public.words SET visuals = '[{"type":"ecos","title":"한국은행 기준금리 최근 5년","stat":"722Y001","item":"0101000","cycle":"M","unit":"%","months":60,"caption":"기준금리가 오르면 대출·예금 금리도 따라 오르는 경향이 있어요."}]'::jsonb WHERE id = 142 AND word = '기준금리';
