UPDATE public.words SET visuals = '[{"type":"ecos","title":"원/달러 환율 최근 5년 (월평균)","stat":"731Y004","item":"0000001/0000100","cycle":"M","unit":"원","months":60,"caption":"숫자가 클수록 1달러를 사는 데 원화가 더 많이 들어요(원화 가치 하락)."}]'::jsonb WHERE id = 144 AND word = '기준환율';
